CREATE TABLE IF NOT EXISTS public.daily_ai_summaries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), summary_date date NOT NULL UNIQUE, tasks_due_today jsonb NOT NULL DEFAULT '[]'::jsonb, sheet_alerts jsonb NOT NULL DEFAULT '[]'::jsonb, client_stats jsonb NOT NULL DEFAULT '[]'::jsonb, ai_summary text, delivered_slack boolean NOT NULL DEFAULT false, delivered_email boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.daily_ai_summaries TO authenticated; GRANT ALL ON public.daily_ai_summaries TO service_role; ALTER TABLE public.daily_ai_summaries ENABLE ROW LEVEL SECURITY; CREATE POLICY "auth read daily summaries" ON public.daily_ai_summaries FOR SELECT TO authenticated USING (true); CREATE INDEX IF NOT EXISTS idx_daily_ai_summaries_date ON public.daily_ai_summaries(summary_date DESC);